import { create_broadcast } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    annoucementDialog: Boolean
  },
  data() {
    return {
      loading: false,
      broadcastName: "",
      description: "",
      dashboard_type: "",
      Password: "",
      broadcastType: null,
      sourceInfo: "",
      imageUrl: ""
    };
  },
  watch: {
    annoucementDialog: {
      async handler() {
        if (this.annoucementDialog == true) {
          // this.broadcastType = "";
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$refs.form.reset();
      this.$refs.form.resetValidation();
      this.$emit("clicked", 0);
    },
    validateURL(url) {
      if (url != "") {
        const urlRegex = /^(ftp|http|https):\/\/[^ "]+$/;
        return urlRegex.test(url);
      }
    },
    validate_data() {
      if (this.$refs.form.validate()) {
        this.Create_broadcast_message();
      }
    },
    async Create_broadcast_message() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_broadcast, {
          input: {
            team_name: this.broadcastName,
            team_description: this.description,
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id,
            team_action_type: "BROAD_CAST"
            // this.broadcastType,
          }
        }));
        var response = JSON.parse(result.data.create_broadcast);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
